        "gloss_kr": "그에게",
        "gloss_en": "to him",
        "syntax": "LFG f-구조에서 οἱ는 동사 φαίνετο의 간접 목적어(OBL_DAT)를 담당하며, [PRED 'αὐτός', CASE dat, θ-ROLE EXPERIENCER]로 분석된다. 생성문법적으로는 [VP [V' φαίνετο [PP οἱ]]]와 같이 동사의 보충어 위치에 병합된다. 레빈슨式 화용론에서 οἱ는 앞선 문맥의 주체인 제우스를 지칭하는 대용어(anaphor)로, 담화 내 지시 대상이 명확한 경우 생략되거나 대명사로 실현된다.",
        "background": "여기서 '그'는 제우스를 가리키며, 신이 인간의 일을 관장하는 주체임을 다시금 강조한다. 신의 내면적 심리(θυμὸν)와 그에 따른 결정(βουλή)이 서사의 중심임을 보여준다. 호메로스는 신의 행동을 인간과 유사한 심리적 과정을 통해 묘사함으로써 서사의 몰입감을 높인다.",
        "etymology": "PIE 재귀 대명사 어근 *se-/*sue-에서 유래한 3인칭 대명사이다. Beekes(EDG)는 이 형태가 PIE *se-의 속격/여격형에서 기원했다고 본다. 라틴어 sē(재귀대명사)와 동계어이며, PIE 후두음이론에 따르면 *se-는 *h₁se-와 같은 재구 가능성이 논의된다. 그리스어에서 3인칭 대명사로 고착화된 이후, 현대 그리스어에서는 강세형/약세형의 구분이 엄격해지며 그 형태가 변화했다."
