        "parse": "prep. (+gen./acc.)",
        "gloss_kr": "~속에, ~따라",
        "gloss_en": "down, according to",
        "syntax": "LFG에서 κατά는 후치사적 용법으로 명사 θυμὸν을 지배하며, [PRED 'κατά<OBJ>', OBJ [PRED 'θυμός', CASE acc]]의 f-구조를 형성한다. 통사적으로는 [PP [P' κατά [DP θυμὸν]]]의 구조를 가지며, 격 지배 이론에 따라 목적어에 대격(accusative)을 부여한다. 레빈슨式 정보구조에서 이 PP는 동사구의 부가어(adjunct)로서 사건의 심리적 배경을 설정하는 역할을 한다.",
        "background": "κατὰ θυμὸν은 '마음속으로'라는 관용구로, 신이나 영웅의 내면적 숙고를 나타내는 전형적인 호메로스식 표현이다. 외부의 행동보다 내면의 결정이 앞서는 서사 구조를 보여준다. 이러한 심리 묘사는 인물의 의도를 명확히 하여 독자에게 사건의 인과관계를 설득력 있게 전달한다.",
        "etymology": "PIE *kmt-('함께, 아래로')에서 유래했다. Chantraine(DELG)은 이 전치사가 그리스어 내에서 '아래로'라는 공간적 의미에서 '따라'라는 추상적 의미로 확장되었다고 분석한다. 히타이트어 kat-('아래')와 동계어이며, PIE *k-m-t-의 후두음적 재구와 관련된 논의가 있다. 현대 그리스어에서도 κατά는 '따라', '대하여' 등의 의미로 널리 쓰이는 필수 전치사다."
