        "gloss_en": "counsel, plan, will",
        "syntax": "LFG f-구조에서 βουλή는 φαίνετο의 주어(SUBJ) 기능을 수행하며, [PRED 'βουλή', CASE nom, θ-ROLE THEME]로 분석된다. 생성문법적으로는 [IP [DP βουλή] [VP φαίνετο]]와 같이 주어 위치에 병합된다. 레빈슨式 정보구조에서 βουλή는 신의 의도를 나타내는 핵심 명사로, 서사의 전개를 결정짓는 중심 정보(focus)를 담고 있다.",
        "background": "βουλή는 신의 지혜와 계획을 상징하는 단어다. 제우스의 βουλή는 트로이아 전쟁의 향방을 결정하며, 인간 영웅들의 운명을 좌우하는 신적 권위를 상징한다. 서사시 전체에서 이 단어는 신의 의지가 인간의 역사에 개입하는 통로로 기능한다.",
        "etymology": "PIE 어근 *gʷel-('의지하다, 원하다')에서 유래했다. Chantraine(DELG)은 이 단어가 '원하는 것'→'계획'으로 의미가 확장되었다고 분석한다. PIE *gʷel-은 후두음이론상 *gʷel-로 재구되며, 라틴어 volō('원하다')와 동계어이다. 현대 그리스어에서는 '의회(βουλή)'라는 정치적 용어로 그 의미가 고착화되어 사용된다."
